// solve.js — zero-copy UTF-8 + SIMD site generator (Rust/WASM).
// The whole pipeline runs in WASM (site.wasm). run(input) keeps the
// contract: a parsed case object (or a JSON string / Uint8Array) -> output
// object. main.ts uses runAllBytes() on the raw cases.json bytes to skip
// the JS JSON.parse/JSON.stringify round-trip entirely.

// ---- JS slugify (v8b, ground truth) — used only by the WASM fallback import
// for strings holding a non-ASCII char outside the WASM NFKD table.
const HAS_NONASCII = /[^\x00-\x7F]/;
function slugifyJs(text) {
  if (!HAS_NONASCII.test(text)) {
    let out = '';
    let gap = false;
    for (let i = 0; i < text.length; i++) {
      const c = text.charCodeAt(i);
      let keep = -1;
      if (c >= 65 && c <= 90) keep = c + 32;
      else if ((c >= 97 && c <= 122) || (c >= 48 && c <= 57)) keep = c;
      if (keep === -1) {
        gap = out.length > 0;
        continue;
      }
      if (gap) out += '-';
      gap = false;
      out += String.fromCharCode(keep);
    }
    if (out.length > 64) out = out.slice(0, 64);
    out = out.replace(/-+$/, '');
    if (out === '') out = 'untitled';
    return out;
  }
  const plain = text.normalize('NFKD').replace(/\p{M}/gu, '');
  let out = '';
  let gap = false;
  for (const ch of plain) {
    let keep = null;
    if (ch >= 'A' && ch <= 'Z') keep = ch.toLowerCase();
    else if ((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9')) keep = ch;
    if (keep === null) {
      gap = out.length > 0;
      continue;
    }
    if (gap) out += '-';
    gap = false;
    out += keep;
  }
  out = out.slice(0, 64).replace(/-+$/, '');
  if (out === '') out = 'untitled';
  return out;
}

// ---- WASM instantiation (top-level await: run() is usable after import) ----
const WASM_B64 = '';
const wasmBytes = Buffer.from(WASM_B64, 'base64');

let instance = null;
let memory = null;
let E = null;

const utf8Encoder = new TextEncoder();
const utf8Decoder = new TextDecoder();

function readU16(ptr, len) {
  const u16 = new Uint16Array(memory.buffer, ptr, len);
  let out = '';
  for (let i = 0; i < len; i += 65536) {
    out += String.fromCharCode.apply(null, u16.subarray(i, Math.min(len, i + 65536)));
  }
  return out;
}

const imports = {
  env: {
    // WASM calls this with (ptr, len) = UTF-16 code units of a string whose
    // slug needs full NFKD handling. JS writes the UTF-8 slug bytes to
    // ptr+8192 (the scratch area) and returns the byte length.
    slugify_fallback: (ptr, len) => {
      const js = readU16(ptr, len);
      const slug = slugifyJs(js);
      const bytes = utf8Encoder.encode(slug);
      new Uint8Array(memory.buffer, ptr + 8192, bytes.length).set(bytes);
      return bytes.length;
    },
  },
};

({ instance } = await WebAssembly.instantiate(wasmBytes, imports));
memory = instance.exports.memory;
E = instance.exports;

// ---- helpers: move bytes between JS and WASM ----
function runWasmBytes(inputBytes, processFn) {
  const ptr = E.arena_ptr();
  new Uint8Array(memory.buffer, ptr, inputBytes.length).set(inputBytes);
  const outLen = processFn(ptr, inputBytes.length);
  const outPtr = E.out_json_ptr();
  // Copy the output out (the arena is reused on the next call).
  const out = new Uint8Array(outLen);
  out.set(new Uint8Array(memory.buffer, outPtr, outLen));
  return out;
}

function runWasmString(inputStr, processFn) {
  const bytes = utf8Encoder.encode(inputStr);
  return utf8Decoder.decode(runWasmBytes(bytes, processFn));
}

// ---- the run() contract: parsed object (or string/bytes) -> output object ----
export function run(input) {
  let json;
  if (typeof input === 'string') json = input;
  else if (input instanceof Uint8Array) json = utf8Decoder.decode(input);
  else json = JSON.stringify(input);
  return JSON.parse(runWasmString(json, (ptr, len) => E.process_one_json(ptr, len)));
}

// ---- fast path for main.ts: whole cases.json bytes -> answers JSON bytes ----
export function runAllBytes(inputBytes) {
  const bytes = inputBytes instanceof Uint8Array ? inputBytes : utf8Encoder.encode(String(inputBytes));
  return runWasmBytes(bytes, (ptr, len) => E.process_all_bytes(ptr, len));
}

// ---- test access ----
export function getWasm() {
  return { E, memory };
}
